/* ============================================================
   Nível Agência: Torre de controlo (todos os clientes, por vertical).
   Lê os datasets de todos os clientes; nada está escrito aqui sobre um cliente em particular.
   ============================================================ */
function agSeal(){
  const cs=AG.clientes,real=cs.filter(c=>c.origens.includes("real")),all=cs.length;
  const o=real.length===0?"demo":real.length===all?"real":"misto",t=o==="demo"?"Demonstração":o==="real"?"Real":`Misto · ${real.length} de ${all} clientes com dados reais`;
  const rows=cs.map(c=>{const r=c.origens.includes("real"),d=c.origens.includes("demo");const so=r&&d?"misto":r?"real":"demo";return`<div class="bl"><b>${esc(c.nome)}</b><span class="seal" data-o="${so}">${so==="misto"?"Misto":so==="real"?"Real":"Demonstração"}</span><span class="m">${c.ficticio?"Cliente fictício de demonstração.":"Cliente real: contexto com fonte e data; séries ainda simuladas onde a fonte não está ligada."}</span></div>`}).join("");
  return{o,t,pop:`<h3>Origem dos dados desta página</h3><p class="s">A Torre agrega todos os clientes. Cada cliente mostra o seu próprio selo nas suas páginas.</p>${rows}`}}
const pubSeal=d=>d.pub.pubd?(pubPend(d)?`<span class="seal" data-o="estimado">Alterações por publicar</span>`:`<span class="seal" data-o="real">Publicada a ${fmtShort(d.pub.pubd.quando)}</span>`):`<span class="muted t-sm">Por publicar</span>`;
function pageTorre(){
  SEAL_OV=agSeal();
  const cs=AG.clientes,live=cs.map(c=>CLS[c.id]),sg=cs.reduce((s,c)=>s+c.sinais_material,0),pend=live.reduce((s,d)=>s+pistasPend(d),0);
  const kp=[["Clientes monitorizados",cs.length,`em ${AG.verticais.length} verticais`],["Sinais acima do limiar",sg,"esta semana"],["Pistas por decidir",pend,"a aguardar a equipa"],["Tempo médio até decidir","—","sem histórico real ainda"]];
  const dec=live.reduce((s,d)=>s+pistasDecididas(d).length,0),cli=live.reduce((s,d)=>s+d.pistas.filter(p=>p.cli&&(p.s==="aceite"||p.s==="ajustada")).length,0);
  const agora={pistas_aceites:String(dec),acoes_cliente:String(cli)};
  const rowFor=c=>{const o=c.origens.includes("real")&&c.origens.includes("demo")?"misto":c.origens.includes("real")?"real":"demo";return`<tr class="go" data-go="${c.id}/visao"><td style="font-weight:600">${esc(c.nome)}${c.ficticio?' <span class="tag">fictício</span>':""}</td><td class="n">${c.sinais_material}</td><td class="n">${pistasPend(CLS[c.id])}</td><td>${pubSeal(CLS[c.id])}</td><td><span class="seal" data-o="${o}">${o==="misto"?"Misto":o==="real"?"Real":"Demonstração"}</span></td></tr>`};
  const porV=AG.verticais.map(v=>{const cl=v.clientes.map(id=>cs.find(c=>c.id===id)),n=cl.reduce((s,c)=>s+c.sinais_material,0),c0=cl[0];
    later(()=>{const h=$(`.spark[data-v="${v.id}"]`);if(h)h.innerHTML=spark(c0.pulso,140,30)});
    return`<div class="panel vblock"><div class="vhead"><div><h3 class="t-h2">${esc(v.nome)}</h3><span class="t-sm muted">${c0.tipo_universo==="tema"?"Tema":"Concorrência, "+c0.n_entidades+" marcas"}</span></div><div class="spark" data-v="${v.id}"></div><span class="t-sm" style="font-weight:600">${n?`${n} ${n===1?"sinal":"sinais"} acima do limiar`:"Sem sinais acima do limiar"}</span></div>
     <div class="tblwrap"><table class="sortable fx" data-tid="cli-${v.id}"><colgroup><col style="width:30%"><col style="width:11%"><col style="width:17%"><col style="width:24%"><col style="width:18%"></colgroup><thead><tr><th data-sort="txt">Cliente</th><th class="n" data-sort="num">Sinais</th><th class="n" data-sort="num">Pistas por decidir</th><th>Vista do cliente</th><th>Dados</th></tr></thead><tbody>${cl.map(rowFor).join("")}</tbody></table></div></div>`}).join("");
  const ratio=({c,p})=>{const s=CLS[c.id].sinais.find(x=>x.id===p.sinal_id);return s&&s.valor!=null&&s.limiar?Math.abs(s.valor)/Math.abs(s.limiar):null};
  const meu=x=>ROLE_PARA[PREFS.role]===x.p.para,fila=cs.flatMap(c=>CLS[c.id].pistas.filter(p=>p.s==="sugerida").map(p=>({c,p}))).sort((a,b)=>meu(b)-meu(a)||(ratio(b)??-1)-(ratio(a)??-1)),
   filaHTML=fila.length?`<div class="panel tblwrap"><table class="sortable" data-tid="fila"><thead><tr><th data-sort="txt">Cliente</th><th data-sort="txt">Pista</th><th class="n" data-sort="num" data-tip="Quantas vezes o sinal ultrapassa o limiar. É só uma sugestão de ordem.">Sinal vs limiar</th><th data-sort="txt">Atribuída a</th><th></th></tr></thead><tbody>${fila.map(x=>{const{c,p}=x,r=ratio(x);return`<tr class="go" data-go="${c.id}/acoes/pistas#${p.id}"><td style="font-weight:600">${esc(c.nome)}</td><td>${esc(p.titulo)}</td><td class="n">${r==null?'<span class="muted">—</span>':nf(r,1)+"×"}</td><td>${esc(p.para)}${meu(x)?' <span class="tag hi">Para ti</span>':""}</td><td class="n"><span class="muted t-sm">Decidir</span></td></tr>`}).join("")}</tbody></table></div>`:emptyHTML("Tudo decidido","Não há pistas à espera da equipa.");
  const body=`<div class="kpis k5">${kp.map(k=>kpiHTML({l:k[0],v:`<span ${typeof k[1]==="number"?`data-count="${k[1]}"`:""}>${k[1]}</span>`,sub:`<span class="muted">${k[2]}</span>`})).join("")}</div>
   ${secHTML("Fila de decisões","Pistas à espera da equipa, em todos os clientes, por ordem sugerida: primeiro as da tua função, depois as de sinal mais forte. A plataforma sugere; a equipa decide.",filaHTML)}
   ${secHTML("Clientes por vertical","Cada vertical traz o seu conjunto de concorrentes por defeito (config/verticals/); o cliente herda e ajusta. «Concorrência» compara marcas; «Tema» acompanha a conversa pública quando a disputa é por atenção e não por quota.",`<div class="vblocks">${porV}</div>`)}`;
  return pheadHTML(`Semana de ${AG.rotulo_semana_atual} · ${esc(AG.agencia.nome)}`,"Torre de controlo","O que mudou nos mercados dos nossos clientes, por vertical, e o que a equipa ainda tem por decidir.",{hero:true})+body}
